def seed_claim_kinds(apps, schema_editor):
    kind = apps.get_model("core", "EventClaimKind")
    for code in (
        "release_signal",
        "source_stated_release",
        "first_observed_usage",
        "rumor",
        "publisher_verification",
        "source_ownership",
        "release_context",
    ):
        kind.objects.using(schema_editor.connection.alias).get_or_create(code=code)


